create function private.battle_hero_names_for(s jsonb) returns text[] language sql stable set search_path='' as $$
 select coalesce(array_agg(coalesce(c.name,s->'heroes'->>(h.n-1)::int,'영웅 #'||h.id) order by coalesce(c.name,s->'heroes'->>(h.n-1)::int,'영웅 #'||h.id) collate "C"),'{}')
 from jsonb_array_elements_text(case when jsonb_typeof(s->'heroIds')='array' then s->'heroIds' else '[]' end) with ordinality h(id,n) left join private.battle_hero_names c on c.hero_id=h.id;
$$;
revoke all on function private.battle_hero_names_for(jsonb) from public,anon,authenticated;
alter table public.guild_war_observations add column attack_heroes text[],add column defense_heroes text[],add column battle_won boolean,add column opponent_name text;
create function private.index_battle_history() returns trigger language plpgsql security definer set search_path='' as $$begin
 new.attack_heroes=private.battle_hero_names_for(new.payload->'attacker');
 new.defense_heroes=private.battle_hero_names_for(new.payload->'defender');
 new.battle_won=case when jsonb_typeof(new.payload->'attackerWon')='boolean' then (new.payload->>'attackerWon')::boolean end;
 new.opponent_name=nullif(new.payload->>'opponentGuild','');return new;
end$$;
revoke all on function private.index_battle_history() from public,anon,authenticated;
create trigger index_battle_history before insert or update of payload on public.guild_war_observations for each row execute function private.index_battle_history();
update public.guild_war_observations set attack_heroes=private.battle_hero_names_for(payload->'attacker'),defense_heroes=private.battle_hero_names_for(payload->'defender'),battle_won=case when jsonb_typeof(payload->'attackerWon')='boolean' then (payload->>'attackerWon')::boolean end,opponent_name=nullif(payload->>'opponentGuild','');
create index battle_defense_heroes_gin on public.guild_war_observations using gin(defense_heroes) where kind='battle';
create index battle_attack_heroes_idx on public.guild_war_observations(attack_heroes,occurred_at desc,id) where kind='battle';
create index guild_history_dates_idx on public.guild_war_observations(guild_name,war_date desc) include(opponent_name);

create function private.history_tokens_match(heroes text[],tokens jsonb) returns boolean language sql immutable set search_path='' as $$
 select not exists(select 1 from jsonb_array_elements(tokens) t where not heroes && array(select jsonb_array_elements_text(t)));
$$;
revoke all on function private.history_tokens_match(text[],jsonb) from public,anon,authenticated;
create function private.search_battle_history(p_tokens jsonb default '[]',p_defense text[] default null,p_attack text[] default null,p_sort text default 'count',p_offset integer default 0,p_limit integer default 20) returns jsonb
language plpgsql stable security definer set search_path='' set plan_cache_mode='force_custom_plan' as $$
declare admin boolean; result jsonb; exact_def text[]; exact_atk text[]; lim integer=least(greatest(coalesce(p_limit,20),1),30); off integer=greatest(coalesce(p_offset,0),0);
begin
 if not private.is_approved_member() then raise exception '권한등급 2등급 이상만 검색할 수 있습니다.' using errcode='42501';end if;
 admin=private.is_admin();
 if p_tokens is null or jsonb_typeof(p_tokens)<>'array' or jsonb_array_length(p_tokens)>12 or octet_length(p_tokens::text)>50000 then raise exception '검색어 오류' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_tokens) t where jsonb_typeof(t)<>'array') then raise exception '검색어 오류' using errcode='22023';end if;
 if p_defense is not null and cardinality(p_defense)<>3 or p_attack is not null and cardinality(p_attack)<>3 then raise exception '영웅 조합 오류' using errcode='22023';end if;
 select array_agg(x order by x collate "C") into exact_def from unnest(p_defense) x;
 select array_agg(x order by x collate "C") into exact_atk from unnest(p_attack) x;
 if exact_def is null and jsonb_array_length(p_tokens)=0 then return jsonb_build_object('groups','[]'::jsonb,'records','[]'::jsonb,'totalGroups',0,'totalRecords',0,'hasMore',false);end if;
 if exact_atk is null then
  with matched as materialized (
   select distinct on(o.source_key) o.source_key,o.attack_heroes,o.battle_won
   from public.guild_war_observations o where o.kind='battle' and cardinality(o.attack_heroes)=3
   and exists(select 1 from public.guild_war_tabs t where t.name=o.guild_name)
   and (exact_def is null or o.defense_heroes=exact_def)
   and (jsonb_array_length(p_tokens)=0 or o.defense_heroes && array(select jsonb_array_elements_text(p_tokens->0)))
   and private.history_tokens_match(o.defense_heroes,p_tokens)
   order by o.source_key,o.created_at desc,o.id
  ), groups as (
   select attack_heroes heroes,count(*) count,count(*) filter(where battle_won=true) wins,count(*) filter(where battle_won=false) losses,
   count(*) filter(where battle_won=true)::numeric/nullif(count(battle_won),0) rate from matched group by attack_heroes
  ), page as (
   select * from groups order by case when p_sort='rate' then rate end desc nulls last,count desc,heroes limit lim offset off
  ) select jsonb_build_object('groups',coalesce((select jsonb_agg(to_jsonb(page)) from page),'[]'),
   'totalGroups',(select count(*) from groups),'totalRecords',(select count(*) from matched),'hasMore',off+lim<(select count(*) from groups)) into result;
 else
  with matched as (
   select distinct on(o.source_key) o.id,o.source_key,o.occurred_at
   from public.guild_war_observations o where o.kind='battle' and o.attack_heroes=exact_atk
   and exists(select 1 from public.guild_war_tabs t where t.name=o.guild_name)
   and (exact_def is null or o.defense_heroes=exact_def)
   and (jsonb_array_length(p_tokens)=0 or o.defense_heroes && array(select jsonb_array_elements_text(p_tokens->0)))
   and private.history_tokens_match(o.defense_heroes,p_tokens)
   order by o.source_key,o.created_at desc,o.id
  ), page as materialized (select * from matched order by occurred_at desc,id limit lim+1 offset off), rows as (
   select o.id,case when admin then o.source_key else o.id::text end source_key,case when admin then o.guild_name end guild_name,o.war_date,o.occurred_at,
   case when admin then o.payload else jsonb_build_object('attacker',private.anonymous_battle_side(o.payload->'attacker'),'defender',private.anonymous_battle_side(o.payload->'defender'),'attackerWon',o.payload->'attackerWon','firstSkillSide',o.payload->'firstSkillSide','castle',o.payload->'castle') end payload
   from page p join public.guild_war_observations o on o.id=p.id order by p.occurred_at desc,p.id limit lim
  ) select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(rows)) from rows),'[]'),'hasMore',(select count(*) from page)>lim) into result;
 end if;
 return result;
end$$;
revoke all on function private.search_battle_history(jsonb,text[],text[],text,integer,integer) from public,anon;
grant execute on function private.search_battle_history(jsonb,text[],text[],text,integer,integer) to authenticated;
create function public.search_battle_history(p_tokens jsonb default '[]',p_defense text[] default null,p_attack text[] default null,p_sort text default 'count',p_offset integer default 0,p_limit integer default 20) returns jsonb
language sql stable security invoker set search_path='' as $$select private.search_battle_history(p_tokens,p_defense,p_attack,p_sort,p_offset,p_limit);$$;
revoke all on function public.search_battle_history(jsonb,text[],text[],text,integer,integer) from public,anon;
grant execute on function public.search_battle_history(jsonb,text[],text[],text,integer,integer) to authenticated;

create function private.fast_guild_history_labels(p_guild text) returns table(war_date date,opponent text)
language plpgsql stable security definer set search_path='' as $$begin
 if not private.can_read_guild_war(p_guild) then return;end if;
 return query select o.war_date,max(o.opponent_name) from public.guild_war_observations o where o.guild_name=p_guild group by o.war_date order by o.war_date desc;
end$$;
revoke all on function private.fast_guild_history_labels(text) from public,anon;
grant execute on function private.fast_guild_history_labels(text) to authenticated;
create or replace function public.guild_war_history_labels(p_guild text) returns table(war_date date,opponent text) language sql stable security invoker set search_path='' as $$select * from private.fast_guild_history_labels(p_guild);$$;
create function private.guild_war_battle_page(p_guild text,p_war_date date,p_direction text,p_castle text default '',p_search text default '',p_offset integer default 0) returns jsonb
language plpgsql stable security definer set search_path='' as $$declare result jsonb;off integer=greatest(coalesce(p_offset,0),0);begin
 if not private.can_read_guild_war(p_guild) then raise exception '이 길드전 열람 권한이 없습니다.' using errcode='42501';end if;
 if off>=150 then return jsonb_build_object('records','[]'::jsonb,'hasMore',false);end if;
 with page as materialized (
 select o.id,o.occurred_at,o.payload from public.guild_war_observations o
 where o.guild_name=p_guild and o.kind='battle' and o.war_date=p_war_date and o.direction=p_direction
 and (coalesce(p_castle,'')='' or o.payload->>'castle'=p_castle)
 and (coalesce(btrim(p_search),'')='' or position(lower(regexp_replace(btrim(p_search),'\s','','g')) in lower(regexp_replace(concat_ws(' ',o.payload->>'castle',o.payload->'attacker'->>'nickname',o.payload->'defender'->>'nickname',o.payload->'attacker'->>'heroes',o.payload->'defender'->>'heroes',o.payload->'attacker'->>'pet',o.payload->'defender'->>'pet'),'\s','','g')))>0)
 order by o.occurred_at desc,o.id limit least(31,150-off) offset off
 ), rows as (select * from page limit 30)
 select jsonb_build_object('records',coalesce((select jsonb_agg(to_jsonb(rows)) from rows),'[]'),'hasMore',off+30<150 and (select count(*) from page)>30) into result;
 return result;
end$$;
revoke all on function private.guild_war_battle_page(text,date,text,text,text,integer) from public,anon;
grant execute on function private.guild_war_battle_page(text,date,text,text,text,integer) to authenticated;
create function public.guild_war_battle_page(p_guild text,p_war_date date,p_direction text,p_castle text default '',p_search text default '',p_offset integer default 0) returns jsonb
language sql stable security invoker set search_path='' as $$select private.guild_war_battle_page(p_guild,p_war_date,p_direction,p_castle,p_search,p_offset);$$;
revoke all on function public.guild_war_battle_page(text,date,text,text,text,integer) from public,anon;
grant execute on function public.guild_war_battle_page(text,date,text,text,text,integer) to authenticated;
